using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using AshkanSocial.Core.Models;
using AshkanSocial.Core.Services;
using AshkanSocial.UI.Theme;
using AshkanSocial.UI.Controls;
namespace AshkanSocial.UI.Forms
{
 public partial class MainForm : Form
 {
  public void ShowCreatorStudio(){Page("Creator Studio");content.Controls.Add(PageBanner("Publish","Creator Studio","Draft, publish and manage content from one focused workspace.",205));content.Controls.Add(StatCard("Drafts",db.Data.Drafts.Count(x=>x.UserId==Session.CurrentUser.Id).ToString(),35,292,180));content.Controls.Add(StatCard("Published",db.Data.Posts.Count(x=>x.UserId==Session.CurrentUser.Id).ToString(),230,292,180));content.Controls.Add(Section("Create",35,420));var editor=new TextBox{Location=new Point(35,455),Size=new Size(Math.Max(560,content.ClientSize.Width-180),90),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,Multiline=true,MaxLength=1000,BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};content.Controls.Add(editor);var save=Btn("Save Draft",35,560,130);save.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(editor.Text))return;db.Data.Drafts.Add(new DraftPost{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Content=editor.Text.Trim(),UpdatedAt=DateTime.Now});LogActivity("Saved a post draft");db.Save();ShowCreatorStudio();};content.Controls.Add(save);var publish=Btn("Publish Now",180,560,140);publish.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(editor.Text))return;db.Data.Posts.Add(new Post{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Content=editor.Text.Trim(),CreatedAt=DateTime.Now});NotifyMentions(editor.Text);LogActivity("Published from Creator Studio");db.Save();ShowFeed();};content.Controls.Add(publish);int y=625;foreach(var d in db.Data.Drafts.Where(x=>x.UserId==Session.CurrentUser.Id).OrderByDescending(x=>x.UpdatedAt).ToList()){var c=Card(y,105);c.Controls.Add(Txt(d.Content,15,12,c.Width-180,45));c.Controls.Add(new Label{Text="Updated "+d.UpdatedAt.ToString("MMM d · HH:mm"),Location=new Point(15,65),AutoSize=true,ForeColor=ThemeColors.TextMuted});var use=Btn("Use",c.Width-145,15,95);use.Anchor=AnchorStyles.Top|AnchorStyles.Right;use.Click+=(ss,ee)=>{editor.Text=d.Content;};c.Controls.Add(use);var del=Btn("Delete",c.Width-145,58,95);del.Anchor=AnchorStyles.Top|AnchorStyles.Right;del.BackColor=ThemeColors.AlertRed;del.Click+=(ss,ee)=>{db.Data.Drafts.Remove(d);db.Save();ShowCreatorStudio();};c.Controls.Add(del);content.Controls.Add(c);y+=118;}}
  void PublishDueScheduledPosts(){if(Session.CurrentUser==null)return;var due=db.Data.ScheduledPosts.Where(x=>x.UserId==Session.CurrentUser.Id&&!x.Published&&x.PublishAt<=DateTime.Now).ToList();foreach(var x in due){db.Data.Posts.Add(new Post{Id=Guid.NewGuid().ToString(),UserId=x.UserId,Content=x.Content,CreatedAt=x.PublishAt});x.Published=true;LogActivity("Published a scheduled post");}if(due.Count>0)db.Save();}
  public void ShowPlanner(){PublishDueScheduledPosts();Page("Content Planner");content.Controls.Add(PageBanner("Schedule","Content Planner","Prepare upcoming posts and keep your publishing workflow organized.",158));content.Controls.Add(Txt("Schedule content for later publishing. Due items are published automatically when Ashkan Social opens.",35,95,780,42));var editor=new TextBox{Location=new Point(35,145),Size=new Size(Math.Max(520,content.ClientSize.Width-220),70),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,Multiline=true,MaxLength=1000,BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};content.Controls.Add(editor);var when=new DateTimePicker{Location=new Point(35,230),Width=230,Format=DateTimePickerFormat.Custom,CustomFormat="yyyy-MM-dd  HH:mm",Value=DateTime.Now.AddHours(1)};content.Controls.Add(when);var schedule=Btn("Schedule Post",285,225,145);schedule.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(editor.Text))return;if(when.Value<=DateTime.Now){MessageBox.Show("Choose a future date and time.","Content Planner");return;}db.Data.ScheduledPosts.Add(new ScheduledPost{Id=Guid.NewGuid().ToString(),UserId=Session.CurrentUser.Id,Content=editor.Text.Trim(),PublishAt=when.Value});LogActivity("Scheduled a post for "+when.Value.ToString("MMM d · HH:mm"));db.Save();ShowPlanner();};content.Controls.Add(schedule);int y=490;foreach(var x in db.Data.ScheduledPosts.Where(x=>x.UserId==Session.CurrentUser.Id).OrderBy(x=>x.PublishAt).ToList()){var c=Card(y,88);c.Controls.Add(Txt((x.Published?"✓ Published  ":"⏱ Scheduled  ")+x.Content,15,12,c.Width-180,38));c.Controls.Add(new Label{Text=x.PublishAt.ToString("MMM d, yyyy · HH:mm"),Location=new Point(15,57),AutoSize=true,ForeColor=ThemeColors.TextMuted});if(!x.Published){var cancel=Btn("Cancel",c.Width-130,22,90);cancel.Anchor=AnchorStyles.Top|AnchorStyles.Right;cancel.BackColor=ThemeColors.AlertRed;cancel.Click+=(ss,ee)=>{db.Data.ScheduledPosts.Remove(x);db.Save();ShowPlanner();};c.Controls.Add(cancel);}content.Controls.Add(c);y+=100;}}
  public void ShowInsights(){Page("Insights");var mine=db.Data.Posts.Where(x=>x.UserId==Session.CurrentUser.Id).ToList();int likes=mine.Sum(x=>x.LikedBy.Count),comments=mine.Sum(x=>x.Comments.Count),saves=mine.Sum(x=>x.SavedBy.Count),reactions=mine.Sum(x=>x.Reactions.Count);content.Controls.Add(PageBanner("Creator analytics","Insights","Understand publishing activity and engagement with a clean portfolio analytics view.",205));content.Controls.Add(StatCard("Posts",mine.Count.ToString(),35,292));content.Controls.Add(StatCard("Engagement",(likes+comments+saves+reactions).ToString("N0"),240,292));content.Controls.Add(StatCard("Saved",saves.ToString(),445,292));var chart=new ModernPanel{Location=new Point(35,420),Size=new Size(Math.Max(620,content.ClientSize.Width-110),270),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right,BackColor=ThemeColors.Surface,BorderRadius=24,BorderColor=ThemeColors.BorderColor,BorderSize=1};chart.Controls.Add(new Label{Text="Engagement trend",Location=new Point(22,18),AutoSize=true,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",12,FontStyle.Bold)});chart.Controls.Add(new Label{Text="Recent publishing performance",Location=new Point(22,47),AutoSize=true,ForeColor=ThemeColors.TextMuted});int[] vals={Math.Max(22,likes+14),Math.Max(35,comments*3+14),Math.Max(28,saves*4+10),Math.Max(52,reactions*2+20),Math.Max(38,likes+comments+12),Math.Max(62,mine.Count*8+15),Math.Max(42,reactions+likes+18),Math.Max(72,likes*2+22)};for(int i=0;i<vals.Length;i++){int h=Math.Min(150,vals[i]);var bar=new ModernPanel{Location=new Point(48+i*68,225-h),Size=new Size(34,h),BackColor=ThemeColors.Primary,BorderRadius=10,BorderSize=0};chart.Controls.Add(bar);}content.Controls.Add(chart);}

 }
}
